#include <iostream>
#include <string>
using namespace std;

class Cat {
public:
    string name;
    int fish;

    Cat(string n, int f) : name(n), fish(f) {}
    void rename(string name);
    void show() const;
};

void Cat::rename(string name) {
    this->name = name;
}

void Cat::show() const {
    cout << name << " 有 " << fish << " 条" << endl;
}

int main() {
    int a = 0;
    cin >> a;

    Cat c1("{oldName}", a);
    c1.rename("{newName}");
    c1.show();
    return 0;
}
